// Dart model classes generated from the `models:` sections of contracts/*.yaml.
import 'dart:io';

import 'package:yaml/yaml.dart';

const _header =
    '// GENERATED by tool/gen_contracts.dart from contracts/*.yaml. Do not edit.';
const _readers = [
  'readDay',
  'readDouble',
  'readList',
  'readNumber',
  'readString',
  'Timestamp',
];

/// `dart format` the generated [code] so the committed file is formatter-stable.
String formatDart(String path, String code) {
  final scratch = File('$path.tmp.dart')..writeAsStringSync(code);
  try {
    final result = Process.runSync(Platform.resolvedExecutable, [
      'format',
      scratch.path,
    ]);
    if (result.exitCode != 0) {
      stderr.writeln(
        'contracts: dart format failed for $path\n${result.stderr}',
      );
      exit(1);
    }
    return scratch.readAsStringSync();
  } finally {
    scratch.deleteSync();
  }
}

/// Generates `<modelsDir>/<file>.g.dart` for every file under `models:` in [root].
/// [documentKeys] maps a contract document to its field keys, for `document:` checks.
Map<String, String> generateModels(
  YamlMap root,
  Map<String, Set<String>> documentKeys,
  Set<String> contractNames,
) {
  final models = root['models'] as YamlMap?;
  if (models == null) return {};
  final directory = root['modelsDir'] as String;
  final package = root['modelsPackage'] as String;
  final all = <String>{
    for (final MapEntry(value: file) in models.entries)
      for (final name in (file as YamlMap).keys) '$name',
  };
  _Field._modelNames = all;
  final result = <String, String>{};
  final generatedNames = {
    for (final MapEntry(:key, :value) in models.entries)
      'package:$package/src/models/$key.dart': {
        for (final name in (value as YamlMap).keys) '$name',
      },
  };
  for (final MapEntry(key: file, value: classes) in models.entries) {
    final parsed = [
      for (final MapEntry(key: name, value: body)
          in (classes as YamlMap).entries)
        _Model('$name', body as YamlMap),
    ];
    for (final model in parsed) {
      model.check(documentKeys);
    }
    result['$directory/$file.g.dart'] = _file(parsed, contractNames, [
      for (final name in models.keys) 'package:$package/src/models/$name.dart',
    ], generatedNames);
  }
  return result;
}

String _file(
  List<_Model> models,
  Set<String> contractNames,
  List<String> siblings,
  Map<String, Set<String>> generatedNames,
) {
  final body = StringBuffer();
  if (models.any((model) => model.usesRows)) {
    body.writeln('''
List<Map<String, dynamic>> _rows(Object? value) => [
  for (final row in value is List ? value : const [])
    if (row is Map) Map<String, dynamic>.from(row),
];
''');
  }
  for (final model in models) {
    body.writeln(model.emit());
  }
  final text = body.toString();
  final used = {
    ..._readers.where((name) => RegExp('\\b$name\\b').hasMatch(text)),
    ...contractNames.where((name) => RegExp('\\b$name\\b').hasMatch(text)),
  }.toList()..sort();
  final import = used.isEmpty
      ? ''
      : "import 'package:icue_firebase/icue_firebase.dart' show ${used.join(', ')};\n\n";
  // Import the hand-written files that declare types these classes reference.
  final own = {for (final model in models) model.name};
  final local = (siblings.toList()..sort())
      .where((path) => _declares(path, text, own, generatedNames))
      .map((path) => "import '$path';\n")
      .join();
  return '$_header\n\n$import$local${local.isEmpty ? '' : '\n'}${text.trimRight()}\n';
}

/// Whether the hand-written file at [packagePath] (or the models generated for it) declares a
/// type that [text] uses and that is not one of [own].
bool _declares(
  String packagePath,
  String text,
  Set<String> own,
  Map<String, Set<String>> generatedNames,
) {
  final match = RegExp(r'^package:(\w+)/(.+)$').firstMatch(packagePath)!;
  final file = File('${_packageRoots[match[1]]}/lib/${match[2]}');
  final names = {
    ...?generatedNames[packagePath],
    if (file.existsSync())
      for (final declared in RegExp(
        r'^(?:abstract )?(?:class|enum|typedef) (\w+)',
        multiLine: true,
      ).allMatches(file.readAsStringSync()))
        declared[1]!,
  };
  return names.any(
    (name) => !own.contains(name) && RegExp('\\b$name\\b').hasMatch(text),
  );
}

/// Package name to its directory, for `package:<name>/...` model imports.
const _packageRoots = {
  'inventory': 'features/inventory',
  'school_library': 'features/library',
};

class _Model {
  _Model(this.name, YamlMap body)
    : doc = body['doc'] as String?,
      idField = body['id'] as String?,
      takesId = body['id'] != null || body['takesId'] == true,
      document = body['document'] as String?,
      fields = [
        for (final MapEntry(:key, :value)
            in (body['fields'] as YamlMap).entries)
          _Field('$key', value),
      ];
  final String name;
  final String? doc;
  final String? idField;
  final bool takesId;
  final String? document;
  final List<_Field> fields;

  bool get usesRows => fields.any(
    (field) =>
        field.from == null &&
        field.listOf != null &&
        !const {'string', 'int'}.contains(field.listOf),
  );

  void check(Map<String, Set<String>> documentKeys) {
    for (final field in fields) {
      final keys = document == null ? null : documentKeys[document];
      if (document != null && keys == null) {
        _fail('$name: unknown document "$document"');
      }
      if (keys != null &&
          field.from == null &&
          !keys.contains(field.path.first)) {
        _fail('$name.${field.name}: "${field.path.first}" is not in $document');
      }
    }
  }

  String emit() {
    final out = StringBuffer();
    if (doc != null) out.write(_doc(doc!, ''));
    out.writeln('class $name {');
    final all = [if (idField != null) _Field.id(idField!), ...fields];
    out.writeln('  const $name({');
    for (final field in all) {
      out.writeln(
        '    ${field.nullable ? '' : 'required '}this.${field.name},',
      );
    }
    out.writeln('  });\n');
    final signature = takesId
        ? 'String id, Map<String, dynamic> data'
        : 'Map<String, dynamic> data';
    out.writeln('  factory $name.fromMap($signature) => $name(');
    for (final field in all) {
      out.writeln('    ${field.name}: ${field.read},');
    }
    out.writeln('  );\n');
    for (final field in all) {
      if (field.doc != null) out.write(_doc(field.doc!, '  '));
      out.writeln('  final ${field.dartType} ${field.name};');
    }
    out.writeln('}');
    return out.toString();
  }
}

class _Field {
  _Field(this.name, Object? spec) {
    final Map<Object?, Object?> map = spec is YamlMap ? spec : {'type': spec};
    final declared = '${map['type']}';
    from = map['from'] as String?;
    nullable = declared.endsWith('?');
    rawType = from == null ? null : declared;
    final type = declared.replaceFirst(RegExp(r'\?$'), '');
    final list = RegExp(r'^list<(.+)>$').firstMatch(type);
    listOf = list?[1];
    base = list == null ? (type.startsWith('map<') ? 'map' : type) : 'list';
    key = '${map['key'] ?? name}';
    doc = map['doc'] as String?;
    defaultValue = map['default']?.toString();
    notEquals = map['notEquals'] as String?;
    present = map['present'] != null;
    length = map['length'] != null;
  }

  _Field.id(this.name)
    : base = 'string',
      listOf = null,
      nullable = false,
      key = 'id',
      rawType = null,
      present = false,
      length = false,
      from = 'id';

  final String name;
  late final String base;
  late final String? listOf;
  late final bool nullable;
  late final String key;
  String? doc;
  String? defaultValue;
  String? from;
  String? notEquals;
  late final bool present;
  late final bool length;
  late final String? rawType;

  List<String> get path => key.split('.');

  /// `data['a']` or, for a dotted key, `(data['a'] as Map?)?['b']`.
  String get source {
    var expression = "data['${path.first}']";
    for (final segment in path.skip(1)) {
      expression = "($expression as Map?)?['$segment']";
    }
    return expression;
  }

  String get dartType {
    if (rawType != null) return rawType!;
    final core = switch (base) {
      'string' || 'day' => 'String',
      'int' => 'int',
      'double' => 'double',
      'bool' => 'bool',
      'num' => 'num',
      'json' => 'Map<String, dynamic>',
      'timestamp' => 'DateTime',
      'list' => 'List<${_elementType(listOf!)}>',
      'map' => 'Map<String, String>',
      final other => other,
    };
    return nullable ? '$core?' : core;
  }

  String _elementType(String element) => switch (element) {
    'string' => 'String',
    'int' => 'int',
    'double' => 'double',
    final other => other,
  };

  String get read {
    if (from != null) return from!;
    final value = source;
    String quoted(String text) {
      if (text == r'$id') return 'id';
      return RegExp(r'^[A-Z]\w*\.\w+$').hasMatch(text) ? text : "'$text'";
    }

    return switch (base) {
      'string' =>
        nullable
            ? '$value as String?'
            : '$value as String? ?? ${quoted(defaultValue ?? '')}',
      'day' => 'readDay($value)',
      'int' when length => '($value as List?)?.length ?? 0',
      'int' =>
        nullable
            ? '($value as num?)?.toInt()'
            : '($value as num? ?? 0).toInt()',
      'num' => nullable ? '$value as num?' : 'readNumber($value)',
      'json' =>
        '$value is Map ? Map<String, dynamic>.from($value as Map) : null',
      'double' =>
        nullable ? '($value as num?)?.toDouble()' : 'readDouble($value)',
      'bool' =>
        present
            ? '$value != null'
            : notEquals != null
            ? "$value != '$notEquals'"
            : '$value == true',
      'timestamp' =>
        '$value is Timestamp ? ($value as Timestamp).toDate() : null',
      'map' =>
        "($value as Map? ?? {}).map((key, value) => MapEntry('\$key', '\$value'))",
      'list' => switch (listOf!) {
        'string' => 'readList<String>($value)',
        'int' => '[for (final number in readList<num>($value)) number.toInt()]',
        final model => '[for (final row in _rows($value)) $model.fromMap(row)]',
      },
      final other when nullable =>
        '$value is Map ? $other.fromMap(Map<String, dynamic>.from($value as Map)) : null',
      final other when _isModel(other) =>
        '$other.fromMap(Map<String, dynamic>.from($value as Map? ?? {}))',
      final other => '$other.parse($value)',
    };
  }

  // Embedded models are the ones declared with `fields:` in `models:`; set by the caller's check.
  static bool _isModel(String type) => _modelNames.contains(type);
  static Set<String> _modelNames = {};
}

String _doc(String text, String indent) =>
    '${text.trim().split('\n').map((line) => '$indent/// $line').join('\n')}\n';

Never _fail(String message) {
  stderr.writeln('contracts: $message');
  exit(1);
}
